function Get-AI5RepositorySnapshot {param([string]$Path);if(!(Test-Path (Join-Path $Path '.git'))-and!(Test-Path (Join-Path $Path '.git') -PathType Leaf)){return[ordered]@{repository=$false;path=$Path}};$branch=(& git -C $Path branch --show-current 2>$null);$head=(& git -C $Path rev-parse HEAD 2>$null);$status=@(& git -C $Path status --porcelain=v2 --untracked-files=all 2>$null);[ordered]@{repository=$true;path=[IO.Path]::GetFullPath($Path);branch=$branch;head=$head;dirty=($status.Count-gt 0);status=@($status);captured_at=[DateTime]::UtcNow.ToString('o')}}
function Get-AI5RepositoryLockKey {param([string]$Path,[string]$Branch);$canonical=([IO.Path]::GetFullPath($Path).TrimEnd('\','/').ToLowerInvariant()+'|'+$Branch.ToLowerInvariant());$sha=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($canonical)))).Replace('-','').Substring(0,24).ToLowerInvariant()}finally{$sha.Dispose()}}
function Enter-AI5RepositoryLock {param([string]$RuntimeRoot,[string]$TaskId,[string]$Path,[string]$Branch,[string]$Writer,[string]$ExpectedHead='');if($Writer-notin@('manus','claude','gemini','codex')){throw 'invalid_writer'};$snapshot=Get-AI5RepositorySnapshot $Path;if(!$snapshot.repository){throw 'repository_not_found'};if($snapshot.dirty){throw 'dirty_worktree'};if($Branch-and$snapshot.branch-ne$Branch){throw 'branch_mismatch'};if($ExpectedHead-and$snapshot.head-ne$ExpectedHead){throw 'source_commit_mismatch'};$dir=Join-Path $RuntimeRoot 'repository-locks';New-Item -ItemType Directory -Force $dir|Out-Null;$key=Get-AI5RepositoryLockKey $Path $snapshot.branch;$lock=Join-Path $dir ($key+'.lock');$stream=[IO.File]::Open($lock,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$record=[ordered]@{task_id=$TaskId;writer=$Writer;pid=$PID;lock_key=$key;snapshot=$snapshot;created_at=[DateTime]::UtcNow.ToString('o')};$bytes=[Text.Encoding]::UTF8.GetBytes(($record|ConvertTo-Json -Depth 8));$stream.Write($bytes,0,$bytes.Length);[ordered]@{path=$lock;record=$record}}catch{$stream.Dispose();Remove-Item -LiteralPath $lock -Force -ErrorAction SilentlyContinue;throw}finally{if($stream){$stream.Dispose()}}}
function Exit-AI5RepositoryLock {param($Lock,[string]$TaskId='');if($Lock-and$Lock.path){if($TaskId-and$Lock.record.task_id-ne$TaskId){throw 'lock_owner_mismatch'};Remove-Item -LiteralPath $Lock.path -Force -ErrorAction SilentlyContinue}}
